/// Where a face's eyes sit in the 100 by 100 box. `x` and `y` are the center of the pair and
/// `spacing` runs center to center. At scale 1 each eye is 4 wide and 11 tall.
struct BotAvatarEyes: Equatable, Sendable {
    var x: Double
    var y: Double
    var spacing: Double
    var scale: Double
}

